# TtZipError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class TtZipError(Exception):
    """
    Typed error enum mapped directly to Swift `throws TTZipError`.
    """

    pass

_UniffiTempTtZipError = TtZipError

class TtZipError:  # type: ignore
    """
    Typed error enum mapped directly to Swift `throws TTZipError`.
    """

    class FileNotFound(_UniffiTempTtZipError):
        def __init__(self, path):
            super().__init__(", ".join([
                "path={!r}".format(path),
            ]))
            self.path = path

        def __repr__(self):
            return "TtZipError.FileNotFound({})".format(str(self))
    _UniffiTempTtZipError.FileNotFound = FileNotFound # type: ignore
    class InvalidPassword(_UniffiTempTtZipError):
        def __init__(self):
            pass

        def __repr__(self):
            return "TtZipError.InvalidPassword({})".format(str(self))
    _UniffiTempTtZipError.InvalidPassword = InvalidPassword # type: ignore
    class CorruptHeader(_UniffiTempTtZipError):
        def __init__(self, details, offset):
            super().__init__(", ".join([
                "details={!r}".format(details),
                "offset={!r}".format(offset),
            ]))
            self.details = details
            self.offset = offset

        def __repr__(self):
            return "TtZipError.CorruptHeader({})".format(str(self))
    _UniffiTempTtZipError.CorruptHeader = CorruptHeader # type: ignore
    class SecurityViolation(_UniffiTempTtZipError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "TtZipError.SecurityViolation({})".format(str(self))
    _UniffiTempTtZipError.SecurityViolation = SecurityViolation # type: ignore
    class EngineError(_UniffiTempTtZipError):
        def __init__(self, code):
            super().__init__(", ".join([
                "code={!r}".format(code),
            ]))
            self.code = code

        def __repr__(self):
            return "TtZipError.EngineError({})".format(str(self))
    _UniffiTempTtZipError.EngineError = EngineError # type: ignore
    class IoError(_UniffiTempTtZipError):
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "TtZipError.IoError({})".format(str(self))
    _UniffiTempTtZipError.IoError = IoError # type: ignore
    class Cancelled(_UniffiTempTtZipError):
        def __init__(self):
            pass

        def __repr__(self):
            return "TtZipError.Cancelled({})".format(str(self))
    _UniffiTempTtZipError.Cancelled = Cancelled # type: ignore

TtZipError = _UniffiTempTtZipError # type: ignore
del _UniffiTempTtZipError


class _UniffiConverterTypeTtZipError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return TtZipError.FileNotFound(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return TtZipError.InvalidPassword(
            )
